create table if not exists forms (id uuid primary key, form_key varchar(100) unique not null, title varchar(200) not null, status varchar(20) not null default 'DRAFT', revision bigint not null default 1, definition jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists form_releases (id uuid primary key, form_id uuid not null references forms(id), version integer not null, package jsonb not null, published_at timestamptz not null default now(), unique(form_id,version));
create table if not exists sessions (id uuid primary key, form_id uuid not null references forms(id), revision bigint not null default 0, locale varchar(16) not null default 'en', answers jsonb not null default '{}'::jsonb, status varchar(20) not null default 'DRAFT', expires_at timestamptz not null default now() + interval '7 days', created_at timestamptz not null default now());
create table if not exists submissions (id uuid primary key, form_id uuid not null references forms(id), session_id uuid not null references sessions(id), envelope jsonb not null, submitted_at timestamptz not null default now());
create table if not exists audit_events (id uuid primary key, action varchar(100) not null, resource_id uuid, detail jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now());
